-- 0078 (M7 hide demo clubs) — PREFLIGHT. READ ONLY: one SELECT, changes nothing.
-- Run immediately before 0078 (staging first; live only after its own approval); 0077 must already be applied.
-- Every part-1 row must be ok = true, or 0078 is not applied. Part 2 is information for the switch decision
-- (counts only, no personal data).
with checks(part, item, ok, detail) as (
  select 1, 'none of 0078''s helper functions exists yet', not exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname in ('demo_clubs_hidden','club_visible_to_me','club_has_my_history','club_readable_by_me','club_id_visible_to_me','club_id_readable_by_me')), ''
  union all select 1, 'clubs policies are the 0077 set (admin write FOR ALL, read)', (select string_agg(policyname || ':' || cmd, ',' order by policyname) from pg_policies where tablename = 'clubs') = 'clubs: admin write:ALL,clubs: read:SELECT', coalesce((select string_agg(policyname || ':' || cmd, ',' order by policyname) from pg_policies where tablename = 'clubs'), 'none')
  union all select 1, 'the switch is not set yet', not exists (select 1 from app_settings where key = 'hide_demo_clubs'), ''
  union all select 1, 'assert_valid_court_slot: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '842d14da33899a48cb53eb356bdf671c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), 'missing')
  union all select 1, 'club_day_slots: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '35ff8264c576bb8bcfb2ced788f2882e' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_day_slots'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_day_slots'), 'missing')
  union all select 1, 'club_discovery: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'aba9a60d5ec08f3a4915bdae0013add9' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_discovery'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_discovery'), 'missing')
  union all select 1, 'coaches_directory: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '66c5da8e2a1c3f7e19f76fc8561ac9d7' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'coaches_directory'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'coaches_directory'), 'missing')
  union all select 1, 'open_matches: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '22e8b948d653fbd83f73ad1e5e0d29e9' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'open_matches'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'open_matches'), 'missing')
  union all select 1, 'club_sports: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '82126283b770d2fb0df6f74934d23657' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_sports'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_sports'), 'missing')
  union all select 1, 'coach_card: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'd385a667f7dc485c77f6d28a33d1e4ac' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'coach_card'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'coach_card'), 'missing')
  union all select 1, 'coaches_at_club: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '8359adcb59abd725afbf05ef8e6e4cca' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'coaches_at_club'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'coaches_at_club'), 'missing')
  union all select 1, 'join_match: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '96298454878cbed0b1623b47f6a738bd' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), 'missing')
  union all select 1, 'match_board: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '5ce4fece9915758fd236e9fc594858c7' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_board'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_board'), 'missing')
  union all select 1, 'match_detail: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'bc1682b6c836fdae0b82a5d4a3463c7a' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_detail'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_detail'), 'missing')
  union all select 1, 'next_free_slot: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '77cb57f78bc88ef47897908b1f7d3530' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'next_free_slot'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'next_free_slot'), 'missing')
  union all select 1, 'post_match: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '65b3a0d219612205d3ceacb6d2f55292' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), 'missing')
  union all select 1, 'quote_price: the version 0078 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'eafe80fffbc3603a409addc7f5532c8b' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'quote_price'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'quote_price'), 'missing')
  union all select 1, 'courts, price_rules, club_media read by anyone; staff write FOR ALL (the 0077 set)', (select string_agg(policyname || ':' || cmd || ':' || coalesce(qual, ''), ',' order by policyname) from pg_policies where tablename = 'courts') = 'courts: read:SELECT:true,courts: staff write:ALL:is_staff_of(club_id)' and (select string_agg(policyname || ':' || cmd || ':' || coalesce(qual, ''), ',' order by policyname) from pg_policies where tablename = 'price_rules') = 'price_rules: read:SELECT:true,price_rules: staff write:ALL:is_staff_of(club_id)' and (select string_agg(policyname || ':' || cmd || ':' || coalesce(qual, ''), ',' order by policyname) from pg_policies where tablename = 'club_media') = 'club_media: read:SELECT:true', ''
  union all select 1, 'matches read policy is the 0077 one', (select qual from pg_policies where tablename = 'matches' and policyname = 'matches: read') = '((status = ''open''::match_status) OR (organizer_id = auth.uid()) OR is_in_match(id) OR is_staff_of(club_id) OR is_admin())', coalesce((select qual from pg_policies where tablename = 'matches' and policyname = 'matches: read'), 'missing')
  union all select 2, 'demo clubs (is_demo = true)', true, (select count(*)::text from clubs where is_demo)
  union all select 2, 'non-demo active clubs (stay public)', true, (select count(*)::text from clubs where active and not is_demo)
  union all select 2, 'upcoming confirmed or pending player bookings at demo clubs (not staff, not walk-in)', true,
    (select count(*)::text from bookings b join clubs c on c.id = b.club_id where c.is_demo and b.player_id is not null
       and b.status in ('confirmed','pending') and b.start_at > now()
       and not exists (select 1 from club_staff s where s.club_id = b.club_id and s.profile_id = b.player_id))
  union all select 2, 'open upcoming games at demo clubs', true,
    (select count(*)::text from matches m join clubs c on c.id = m.club_id where c.is_demo and m.status = 'open' and m.start_at > now())
)
select part, item, ok, detail from checks order by part, item;
